/** Host-native instructions generated by `resonant-code init`. */
import { PRODUCT_VERSION, PROTOCOL_VERSION } from '../version.ts';

export type HostAdapter = 'codex' | 'claude';

export function renderHostSkill(adapter: HostAdapter): string {
  const hostName = adapter === 'codex' ? 'Codex' : 'Claude Code';
  return `---
name: resonant-code
description: "Use the resonant-code CLI before and after concrete coding changes."
metadata:
  version: "${PRODUCT_VERSION}"
  protocol: "${PROTOCOL_VERSION}"
---

# Resonant Code

Use this skill for implementation, bug fixes, features, refactors, migrations,
tests, and other concrete repository changes performed by ${hostName}.

The CLI is the deterministic control plane. It never calls a model. You retain
semantic task understanding, select exact evidence windows, propose bounded
relations, implement the change, and attest semantic outcomes.

## Change lifecycle

1. Run \`resonant-code change prepare . --task "<task>" --change-type <type> --target <path> --json\`.
2. If status is \`needs-interpretation\`, supply the listed task fields and rerun.
3. If status is \`guidance-overflow\`, use your task judgment to select relevant
   optional IDs, save \`{ "considerIds": [...], "rationale": "..." }\`, and rerun
   with \`--selection-file\`. Do not omit mandatory guidance.
4. Implement only after prepare returns a session path. Follow the delivered
   required, avoid, tension, and consider sections.
5. Write semantic attestations and approved exceptions only. Do not invent
   changed files or check results.
6. Run \`resonant-code change complete --session <path> --evaluation-file <path> --json\`.

The CLI snapshots the Git worktree at prepare, collects the actual diff at
complete, and runs only commands explicitly mapped in
\`.resonant-code/checks.json\`.

## Repository context

Select exact decision-relevant source windows and run
\`resonant-code context prepare . --evidence <file>:<start>-<end> --json\`.
Generate a proposal against that contract, commit it with
\`resonant-code context commit\`, and use \`resonant-code context approve\` only after a
human review. Snippet currency does not prove semantic truth.

## Boundaries

- Do not parse or merge Playbook policy in this skill.
- Do not turn token overlap into a semantic relation.
- Do not evaluate guidance that prepare did not deliver.
- Use \`resonant-code status . --json\` and \`resonant-code doctor . --json\` for readiness.
`;
}

export function renderHostPointerBlock(
  adapter: HostAdapter,
  markers: { start: string; end: string },
): string {
  const skillPath = adapter === 'codex'
    ? '.agents/skills/resonant-code/SKILL.md'
    : '.claude/skills/resonant-code/SKILL.md';
  return [
    markers.start,
    `For concrete coding changes, read and follow \`${skillPath}\`.`,
    'Use the `resonant-code` CLI as the deterministic change-harness control plane.',
    markers.end,
  ].join('\n');
}
